import type {
  DictionaryDefinition,
  DictionaryIndex,
  DictionaryLetterPack,
} from '@alice-wallet/alice-content/src/dictionary-types';
import { letterOfSlug } from './dictionary';

// The dictionary pack is static JSON generated by
// scripts/build-dictionary-pack.mjs into public/dictionary/<lang>/, served
// from the app's own origin: same bytes in the browser, in the Tauri webview
// and offline on desktop. The index is loaded once; a letter's bodies are
// fetched when a term of that letter is opened or quoted.

export const DICTIONARY_LANG = 'fr';

const cache = new Map<string, Promise<unknown>>();

function fetchJson<T>(url: string): Promise<T> {
  const cached = cache.get(url);
  if (cached) return cached as Promise<T>;
  const pending = fetch(url).then(async response => {
    if (!response.ok) throw new Error(`Dictionary pack unavailable (${response.status}): ${url}`);
    return (await response.json()) as T;
  });
  // A failed fetch must not poison the cache: the next call tries again.
  pending.catch(() => { cache.delete(url); });
  cache.set(url, pending);
  return pending;
}

export function fetchDictionaryIndex(lang = DICTIONARY_LANG): Promise<DictionaryIndex> {
  return fetchJson<DictionaryIndex>(`/dictionary/${lang}/index.json`);
}

export function fetchDictionaryLetter(letter: string, lang = DICTIONARY_LANG): Promise<DictionaryLetterPack> {
  if (!/^[a-z]$/.test(letter)) return Promise.reject(new Error(`Not a dictionary letter: ${letter}`));
  return fetchJson<DictionaryLetterPack>(`/dictionary/${lang}/letters/${letter}.json`);
}

/** One definition by slug, or null when the dictionary has no such term. */
export async function fetchDefinition(slug: string, lang = DICTIONARY_LANG): Promise<DictionaryDefinition | null> {
  if (!/^[a-z0-9-]+$/.test(slug)) return null;
  const pack = await fetchDictionaryLetter(letterOfSlug(slug), lang);
  return pack.entries.find(entry => entry.slug === slug) ?? null;
}

/**
 * Warm the index when the browser is idle, so the first question of a chat
 * finds it in memory: the turn-context bridge gives a provider 1.5 s, and a
 * cold fetch of the index would spend most of it.
 */
export function prefetchDictionaryIndex(): void {
  if (typeof window === 'undefined') return;
  const start = () => { fetchDictionaryIndex().catch(() => { /* the dictionary is optional */ }); };
  const idle = (window as Window & { requestIdleCallback?: (cb: () => void, options?: { timeout: number }) => number }).requestIdleCallback;
  if (idle) idle(start, { timeout: 4_000 });
  else setTimeout(start, 2_500);
}
